semaphore room=200; //场馆最大容纳人数
semaphore mutex=1; //扫码操作互斥访问
visitor(){
    P(room);
    P(mutex);
    扫码登记录入信息;
    V(mutex);
    场馆内参观;
    P(mutex);
    扫码注销登记;
    V(mutex);
    V(room);
}

semaphore empty=1; //盘子空
 semaphore apple=0; //苹果
 semaphore orange=0; //桔子
father(){
    while(1){
        P(empty);
        随机放苹果或桔子;
        if(放苹果) V(apple);
        else V(orange);
    }
}
daughter(){
    while(1){
        P(apple);
        取苹果;
        V(empty);
        吃苹果;
    }
}
son(){
    while(1){
        P(orange);
        取桔子;
        V(empty);
        吃桔子;
    }
}

semaphore s1=0; //关门完成，司机启动
 semaphore s2=0; //停车完成，售票员开门
driver(){
    while(1){
        P(s1);
        启动车辆;
        正常行车;
        到站停车;
        V(s2);
    }
}
conductor(){
    while(1){
        关车门;
        V(s1);
        售票;
        P(s2);
        开车门;
        乘客上下车;
    }
}
